//! Corpus-wide tests over the vendored and synthetic ADR fixtures.
//!
//! Everything here runs offline. The real-world trees under `fixtures/corpus/` are the committed,
//! pinned copies described in `fixtures/corpus/ATTRIBUTION.md`; the synthetic tree is generated by
//! `scripts/generate-corpus.py`. The tests are deliberately recursive so a new file is covered the
//! moment it lands, and count their inputs so a corpus that silently disappears fails loudly.

use std::collections::BTreeSet;
use std::fs;
use std::panic::{self, AssertUnwindSafe};
use std::path::{Path, PathBuf};
use std::process::{Command, Output};
use std::sync::Mutex;

use adrlint::adr::{self, Document};
use adrlint::config::{AdrConfig, MarkdownConfig};
use adrlint::diagnostics::{Diagnostic, Severity};
use adrlint::lock;
use adrlint::markdown;
use adrlint::rules;
use tempfile::TempDir;

/// The three real-world trees, copied from upstream at pinned commits.
const REAL_WORLD: [&str; 3] = ["madrlint", "adr-manager", "log4brains"];

fn corpus() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("fixtures/corpus")
}

fn markdown_config() -> MarkdownConfig {
    MarkdownConfig::default()
}

/// Every `.md` file under `root`, recursively, sorted by path.
fn markdown_files(root: &Path) -> Vec<PathBuf> {
    let mut files = Vec::new();
    walk(root, &mut files);
    files.sort();
    files
}

fn walk(directory: &Path, files: &mut Vec<PathBuf>) {
    let entries = fs::read_dir(directory).unwrap_or_else(|error| panic!("reading {}: {error}", directory.display()));
    for entry in entries {
        let path = entry.expect("directory entry").path();
        if path.is_dir() {
            walk(&path, files);
        } else if path.extension().is_some_and(|extension| extension == "md") {
            files.push(path);
        }
    }
}

/// Every directory under `root` that contains at least one Markdown file, plus `root` itself.
fn markdown_directories(root: &Path) -> Vec<PathBuf> {
    let mut directories = BTreeSet::new();
    for file in markdown_files(root) {
        if let Some(parent) = file.parent() {
            directories.insert(parent.to_path_buf());
        }
    }
    directories.into_iter().collect()
}

fn read(path: &Path) -> String {
    String::from_utf8(fs::read(path).unwrap_or_else(|error| panic!("reading {}: {error}", path.display())))
        .unwrap_or_else(|error| panic!("{} is not valid UTF-8: {error}", path.display()))
}

/// The findings a single document produces: the MADR rules and the Markdown layer.
fn findings(source: &str, path: &Path) -> Vec<Diagnostic> {
    let document = adr::parse(source);
    let mut findings = rules::check_document(&document, path, &corpus());
    findings.extend(markdown::check(source, path, &markdown_config()));
    findings
}

fn has_errors(findings: &[Diagnostic]) -> bool {
    findings.iter().any(|finding| finding.severity.is_error())
}

fn codes(findings: &[Diagnostic]) -> Vec<&'static str> {
    findings.iter().map(|finding| finding.code).collect()
}

/// Recursively copies `source` into `destination`.
fn copy_tree(source: &Path, destination: &Path) {
    fs::create_dir_all(destination).unwrap_or_else(|error| panic!("creating {}: {error}", destination.display()));
    for entry in fs::read_dir(source).unwrap_or_else(|error| panic!("reading {}: {error}", source.display())) {
        let entry = entry.expect("directory entry");
        let from = entry.path();
        let to = destination.join(entry.file_name());
        if from.is_dir() {
            copy_tree(&from, &to);
        } else {
            fs::copy(&from, &to).unwrap_or_else(|error| panic!("copying {}: {error}", from.display()));
        }
    }
}

fn run(arguments: &[&std::ffi::OsStr]) -> Output {
    Command::new(env!("CARGO_BIN_EXE_adrlint"))
        .args(arguments)
        .output()
        .expect("running adrlint")
}

fn stderr(output: &Output) -> String {
    String::from_utf8_lossy(&output.stderr).into_owned()
}

/// The rule codes the tool currently implements. A corpus finding outside this set means a rule
/// emitted a code nobody documents, which breaks suppression and the `[rules]` configuration.
fn is_known_code(code: &str) -> bool {
    let madr = [
        "MADR01a", "MADR01b", "MADR01c", "MADR01d", "MADR02", "MADR03a", "MADR03b", "MADR04", "MADR05", "MADR06",
        "MADR07a", "MADR07b", "MADR08a", "MADR08b", "MADR12a", "MADR12b", "MADR12c", "MADR12d", "MADR21", "MADR31",
        "MADR41a", "MADR41b", "MADR42", "MADR43", "MADR44", "ADR50", "ADR51",
    ];
    if madr.contains(&code) {
        return true;
    }
    code.strip_prefix("MD")
        .is_some_and(|digits| digits.len() == 3 && digits.bytes().all(|byte| byte.is_ascii_digit()))
}

#[test]
fn should_parse_every_corpus_file_without_panicking() {
    let files = markdown_files(&corpus());
    assert!(
        files.len() >= 60,
        "expected a non-trivial corpus, found {} Markdown files",
        files.len()
    );

    let mut real_world = 0;
    for path in &files {
        let source = read(path);
        let document = panic::catch_unwind(|| adr::parse(&source))
            .unwrap_or_else(|_| panic!("parse panicked on {}", path.display()));

        if source.is_empty() {
            assert_eq!(
                document,
                Document::default(),
                "{} should parse to an empty model",
                path.display()
            );
            continue;
        }
        assert!(
            !document.headings.is_empty(),
            "{} parsed to a document with no headings",
            path.display()
        );

        if REAL_WORLD.iter().any(|tree| path.starts_with(corpus().join(tree))) {
            real_world += 1;
            assert!(
                document.headings.iter().any(|heading| heading.level == 1),
                "real-world ADR {} has no level-1 title",
                path.display()
            );
        }
    }
    assert!(
        real_world >= 40,
        "expected at least 40 real-world ADRs, found {real_world}"
    );
}

#[test]
fn should_format_every_corpus_file_idempotently() {
    let temp = TempDir::new().expect("temporary directory");
    let files = markdown_files(&corpus());
    assert!(files.len() >= 60);

    for (index, path) in files.iter().enumerate() {
        let name = path.file_name().expect("file name").to_string_lossy();
        let copy = temp.path().join(format!("{index:03}-{name}"));
        let source = read(path);
        fs::write(&copy, &source).expect("writing the copy");

        let first = markdown::format(&source, &copy, &markdown_config())
            .unwrap_or_else(|error| panic!("formatting {} failed: {error}", path.display()));
        assert!(
            std::str::from_utf8(first.as_bytes()).is_ok(),
            "formatting {} produced invalid UTF-8",
            path.display()
        );
        fs::write(&copy, &first).expect("writing the first pass");
        let reread = fs::read_to_string(&copy).expect("the first pass must write valid UTF-8");

        let second = markdown::format(&reread, &copy, &markdown_config())
            .unwrap_or_else(|error| panic!("re-formatting {} failed: {error}", path.display()));
        assert_eq!(
            second,
            first,
            "formatting {} is not idempotent; the second pass changed the document",
            path.display()
        );
        assert!(std::str::from_utf8(second.as_bytes()).is_ok());
    }
}

#[test]
fn should_keep_the_content_hash_stable_across_formatting() {
    let mut checked = 0;
    for path in markdown_files(&corpus()) {
        let source = read(&path);
        if has_errors(&findings(&source, &path)) {
            continue;
        }

        let formatted = markdown::format(&source, &path, &markdown_config())
            .unwrap_or_else(|error| panic!("formatting {} failed: {error}", path.display()));
        let before = lock::canonical_hash(&adr::parse(&source));
        let after = lock::canonical_hash(&adr::parse(&formatted));
        assert_eq!(
            before,
            after,
            "formatting {} changed its canonical content hash",
            path.display()
        );
        checked += 1;
    }

    assert!(
        checked >= 30,
        "expected at least 30 lint-clean corpus files to exercise hashing, found {checked}"
    );
}

#[test]
fn should_not_panic_on_truncated_input() {
    let files = markdown_files(&corpus());
    assert!(files.len() >= 60);

    let failures = Mutex::new(Vec::new());
    let threads = std::thread::available_parallelism()
        .map(std::num::NonZeroUsize::get)
        .unwrap_or(4)
        .clamp(1, 8);
    let chunk = files.len().div_ceil(threads);

    std::thread::scope(|scope| {
        for chunk in files.chunks(chunk) {
            let failures = &failures;
            scope.spawn(move || {
                for path in chunk {
                    let source = read(path);
                    for length in prefixes(&source) {
                        let prefix = &source[..length];
                        let path = path.as_path();
                        let outcome = panic::catch_unwind(AssertUnwindSafe(|| {
                            let document = adr::parse(prefix);
                            let _ = lock::canonical_hash(&document);
                            let _ = rules::check_document(&document, path, &corpus());
                            let _ = markdown::check(prefix, path, &markdown_config());
                        }));
                        if outcome.is_err() {
                            failures
                                .lock()
                                .expect("failure list")
                                .push((path.to_path_buf(), length));
                        }
                    }
                }
            });
        }
    });

    let failures = failures.into_inner().expect("failure list");
    assert!(
        failures.is_empty(),
        "truncated input panicked on {} boundaries, first: {:?}",
        failures.len(),
        failures.first()
    );
}

/// Byte prefixes covering every offset up to 512 bytes and every 64th byte beyond that, restricted
/// to character boundaries so a multi-byte character is never split.
fn prefixes(source: &str) -> Vec<usize> {
    let mut points = BTreeSet::new();
    for length in 0..=source.len().min(512) {
        points.insert(length);
    }
    for length in (0..=source.len()).step_by(64) {
        points.insert(length);
    }
    points.insert(source.len());
    points
        .into_iter()
        .filter(|length| source.is_char_boundary(*length))
        .collect()
}

#[test]
fn should_lint_the_synthetic_corpus_cleanly() {
    let directory = corpus().join("synthetic");
    let files = markdown_files(&directory);
    assert!(
        files.len() >= 30,
        "expected at least 30 synthetic ADRs, found {}",
        files.len()
    );

    for path in &files {
        let source = read(path);
        let found = findings(&source, path);
        let errors = found
            .iter()
            .filter(|finding| finding.severity == Severity::Error)
            .map(|finding| format!("{}:{} {}", finding.line, finding.code, finding.message))
            .collect::<Vec<_>>();
        assert!(
            errors.is_empty(),
            "{} should lint clean, got:\n{}",
            path.display(),
            errors.join("\n")
        );
    }
}

#[test]
fn should_report_only_known_codes_on_real_world_adrs() {
    let mut checked = 0;
    let mut observed = BTreeSet::new();

    for tree in REAL_WORLD {
        let root = corpus().join(tree);
        let files = markdown_files(&root);
        assert!(!files.is_empty(), "{tree} should contain ADRs");

        for path in &files {
            let source = read(path);
            let found = findings(&source, path);
            for code in codes(&found) {
                assert!(
                    is_known_code(code),
                    "{} reported undocumented code {code}",
                    path.display()
                );
                observed.insert(code);
            }
            checked += 1;
        }

        // Directory-level rules are only reachable through a scan, so exercise them too.
        for directory in markdown_directories(&root) {
            let scanned = adrlint::discovery::scan(&directory)
                .unwrap_or_else(|error| panic!("scanning {}: {error}", directory.display()));
            for finding in rules::check_directory(&scanned, &AdrConfig::default()) {
                assert!(
                    is_known_code(finding.code),
                    "{} reported undocumented directory code {}",
                    directory.display(),
                    finding.code
                );
                observed.insert(finding.code);
            }
        }
    }

    assert!(checked >= 40, "expected at least 40 real-world ADRs, found {checked}");
    for expected in ["MADR44", "MD004"] {
        assert!(
            observed.contains(expected),
            "expected the corpus to exercise {expected}, observed {observed:?}"
        );
    }
}

#[test]
fn should_be_deterministic_and_valid_json() {
    let temp = TempDir::new().expect("temporary directory");
    let copied = temp.path().join("madrlint");
    copy_tree(&corpus().join("madrlint"), &copied);

    let lint = || {
        run(&[
            std::ffi::OsStr::new("--no-color"),
            std::ffi::OsStr::new("lint"),
            std::ffi::OsStr::new("--format"),
            std::ffi::OsStr::new("json"),
            copied.as_os_str(),
        ])
    };
    let first = lint();
    let second = lint();

    assert_eq!(
        first.status.code(),
        second.status.code(),
        "exit code changed between identical runs; stderr: {}",
        stderr(&first)
    );
    assert_ne!(
        first.status.code(),
        Some(2),
        "lint aborted instead of reporting; stderr: {}",
        stderr(&first)
    );
    assert_eq!(first.stdout, second.stdout, "JSON output is not deterministic");

    let diagnostics: Vec<serde_json::Value> =
        serde_json::from_slice(&first.stdout).expect("lint --format json should emit valid JSON");
    assert!(!diagnostics.is_empty(), "the madrlint copy should produce findings");
    for diagnostic in &diagnostics {
        assert!(diagnostic["code"].is_string(), "finding has no code: {diagnostic}");
        assert!(
            diagnostic["severity"].is_string(),
            "finding has no severity: {diagnostic}"
        );
        assert!(diagnostic["path"].is_string(), "finding has no path: {diagnostic}");
        assert!(diagnostic["line"].is_u64(), "finding has no line: {diagnostic}");
    }
}

#[test]
fn should_round_trip_the_full_corpus_through_the_cli() {
    let temp = TempDir::new().expect("temporary directory");
    let copied = temp.path().join("corpus");
    copy_tree(&corpus(), &copied);

    let directories = markdown_directories(&copied);
    assert!(
        directories.len() >= 6,
        "expected several ADR directories, found {}",
        directories.len()
    );
    let paths = directories.iter().map(|path| path.as_os_str()).collect::<Vec<_>>();

    let format = |check: bool| {
        let mut arguments = vec![std::ffi::OsStr::new("format")];
        if check {
            arguments.push(std::ffi::OsStr::new("--check"));
        }
        arguments.extend(paths.iter().copied());
        run(&arguments)
    };

    let first = format(false);
    assert_eq!(
        first.status.code(),
        Some(0),
        "format failed; stderr: {}",
        stderr(&first)
    );

    let check = format(true);
    assert_eq!(
        check.status.code(),
        Some(0),
        "format --check failed after format; stdout: {}\nstderr: {}",
        String::from_utf8_lossy(&check.stdout),
        stderr(&check)
    );

    let lint = run(&{
        let mut arguments = vec![std::ffi::OsStr::new("--no-color"), std::ffi::OsStr::new("lint")];
        arguments.extend(paths.iter().copied());
        arguments
    });
    assert!(
        matches!(lint.status.code(), Some(0) | Some(1)),
        "lint must exit 0 or 1, not {:?}; stderr: {}",
        lint.status.code(),
        stderr(&lint)
    );

    let before = snapshot(&copied);
    let second = format(false);
    assert_eq!(
        second.status.code(),
        Some(0),
        "the second format failed; stderr: {}",
        stderr(&second)
    );
    assert_eq!(before, snapshot(&copied), "a second format changed files");
}

/// Every file under `root` mapped to its bytes, so a no-op pass can be asserted exactly.
fn snapshot(root: &Path) -> std::collections::BTreeMap<PathBuf, Vec<u8>> {
    fn collect(root: &Path, directory: &Path, files: &mut std::collections::BTreeMap<PathBuf, Vec<u8>>) {
        for entry in fs::read_dir(directory).unwrap_or_else(|error| panic!("reading {}: {error}", directory.display()))
        {
            let path = entry.expect("directory entry").path();
            if path.is_dir() {
                collect(root, &path, files);
            } else {
                let relative = path.strip_prefix(root).expect("a path under the snapshot root");
                files.insert(
                    relative.to_path_buf(),
                    fs::read(&path).expect("reading a snapshotted file"),
                );
            }
        }
    }
    let mut files = std::collections::BTreeMap::new();
    collect(root, root, &mut files);
    files
}

/// The current CLI aborts the whole run with exit code 2 on the first non-UTF-8 ADR, so this test
/// documents the contract the release needs and stays ignored until the reader reports the file.
#[test]
#[ignore = "defect: lint exits 2 on a non-UTF-8 ADR instead of reporting it and continuing"]
fn should_reject_non_utf8_adrs_without_aborting_the_run() {
    let temp = TempDir::new().expect("temporary directory");
    let good = temp.path().join("0001-use-postgresql.md");
    let bad = temp.path().join("0002-corrupt-bytes.md");
    fs::write(
        &good,
        "# Use PostgreSQL\n\n## Context and Problem Statement\n\nThe service needs a store.\n\n\
         ## Considered Options\n\n* PostgreSQL\n* SQLite\n\n## Decision Outcome\n\n\
         Chosen option: \"PostgreSQL\", because the team operates it.\n",
    )
    .expect("writing the valid ADR");
    fs::write(&bad, b"# Corrupt\n\n\xff\xfe not UTF-8\n").expect("writing the invalid ADR");

    let output = run(&[
        std::ffi::OsStr::new("--no-color"),
        std::ffi::OsStr::new("lint"),
        std::ffi::OsStr::new("--format"),
        std::ffi::OsStr::new("json"),
        temp.path().as_os_str(),
    ]);

    assert_ne!(
        output.status.code(),
        Some(2),
        "lint aborted the run; stderr: {}",
        stderr(&output)
    );
    assert_eq!(output.status.code(), Some(1), "a broken ADR should fail the run");
    assert!(
        String::from_utf8_lossy(&output.stdout).contains("0002-corrupt-bytes.md"),
        "the bad file should be reported; stdout: {}",
        String::from_utf8_lossy(&output.stdout)
    );
}
